{"file_path":"C:\Temp\ws\heap-summary.js","content":"// Debug: summarises .heapsnapshot files without printing them: node counts by name, and one node's retainers.
const fs = require('node:fs');
const load = (f) => {
  const s = JSON.parse(fs.readFileSync(f, 'utf8'));
  const nf = s.snapshot.meta.node_fields.length, ef = s.snapshot.meta.edge_fields.length;
  const nodes = [];
  for (let i = 0, e = 0; i < s.nodes.length; i += nf) {
    const n = { name: s.strings[s.nodes[i + 1]], edges: [], retainers: [] };
    n.edgeStart = e; e += s.nodes[i + 4] * ef; nodes.push(n);
  }
  nodes.forEach((n, idx) => {
    for (let k = 0; k < s.nodes[idx * nf + 4]; k++) {
      const to = nodes[s.edges[n.edgeStart + k * ef + 2] / nf];
      to.retainers.push({ from: n, edge: s.edges[n.edgeStart + k * ef + 1] });
    }
  });
  return nodes;
};
const count = (nodes) => nodes.reduce((m, n) => m.set(n.name, (m.get(n.name) || 0) + 1), new Map());
exports.summarize = (a, b, top) => {
  const ca = count(load(a)), cb = count(load(b));
  [...cb].map(([k, v]) => [k, v - (ca.get(k) || 0)]).sort((x, y) => y[1] - x[1]).slice(0, top).forEach(([k, d]) => console.log(`+${d}	${k}`));
};
exports.retainers = (f, name, depth) => {
  let n = load(f).find((x) => x.name === name);
  for (let i = 0; n && i < depth; i++) { console.log('  <- ' + n.name); n = n.retainers[0]?.from; }
};"}

